/**
 * Generates the Cursor adapter: a preToolUse command hook that rewrites
 * shell commands into a shaving wrapper, so the terminal output Cursor
 * feeds to the model is already shaved (Cursor ≤ current docs ship no
 * output-replacement contract for native shell tools — see below).
 *
 * Verified against the Cursor hooks documentation (docs/hooks +
 * docs/reference/third-party-hooks, checked 2026-11-02; see VERIFY.md):
 *  - afterShellExecution is observe-only (command/output/duration/sandbox,
 *    no output schema) — it cannot change what the model sees
 *  - postToolUse can replace output only for MCP tools
 *    (updated_mcp_tool_output); for Shell it only offers additional_context,
 *    which ADDS context on top of the untouched raw output
 *  - preToolUse documents updated_input: "Modified tool input to use
 *    instead" — the official, supported way to change a command before it
 *    runs. That is the mechanism this adapter uses.
 *  - the wrapper rewrites the command to:
 *      node "<script>" <base64 of original command> tsh-cursor-wrap
 *    and that wrapper runs the real command (shell:true), captures
 *    stdout/stderr, shaves them with the inlined engine, prints the shaved
 *    form, and exits with the child's exit code.
 *  - hook-mode output is ALWAYS {"permission":"allow"}-shaped JSON with
 *    exit 0: Cursor's permission hooks BLOCK on invalid/missing output, so
 *    a valid allow is the fail-open shape; crashes/timeouts (exit != 2)
 *    fail open by design too.
 *  - conservative wrap whitelist: only commands the engine has a named
 *    rule for (installs / test runners / compilers / bundler builds /
 *    curl-wget) plus `npm|pnpm|yarn|bun test` spellings. Sandboxed
 *    commands, non-Shell tools, and already-wrapped commands are passed
 *    through untouched; interactive/watch commands never match the
 *    whitelist in the first place.
 *  - project hooks run with cwd = project root, so both files are written
 *    by absolute paths at install time (Cursor hooks are project-level;
 *    no marketplace payload exists for this — project hooks.json is the
 *    supported route).
 */
export declare const CURSOR_HOOK_MARKER = "tokenshave \u2014 generated by `npx tokenshave install` (Cursor hook)";
export interface CursorHookFiles {
    hooksJson: string;
    wrapJs: string;
}
export declare function generateCursorHookFiles(generatedAt: string, version: string, command: string, engineBundle?: string): Promise<CursorHookFiles>;
